const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find all flights going TO JFK
const toJFK = db.prepare(\"SELECT * FROM flights WHERE destination = 'JFK'\").all();
console.log('=== Direct flights TO JFK ===');
console.log(JSON.stringify(toJFK, null, 2));

// For one-stop routes: find intermediate cities that connect to JFK
// i.e. origin -> X (leg1), then X -> JFK (leg2)
const jfkOrigins = toJFK.map(f => f.origin);
console.log('\\nCities with direct flights to JFK:', [...new Set(jfkOrigins)]);

// Now find all flights whose destination is one of those intermediate cities
if (jfkOrigins.length > 0) {
  const placeholders = jfkOrigins.map(() => '?').join(',');
  const leg1s = db.prepare('SELECT * FROM flights WHERE destination IN (' + placeholders + ')').all(...jfkOrigins);
  console.log('\\n=== Potential Leg 1 flights (to intermediate city) ===');
  console.log(JSON.stringify(leg1s, null, 2));
}
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check ALL unique origin-destination pairs to find any possible one-stop routes to JFK
// that DON'T start from JFK itself
const allFlights = db.prepare('SELECT flight_id, origin, destination, departure_time, arrival_time, cabin_prices_json, dates_json, source_skill FROM flights').all();

// Build adjacency: city -> [{flight, dest}]
const adj = {};
for (const f of allFlights) {
  if (!adj[f.origin]) adj[f.origin] = [];
  adj[f.origin].push(f);
}

// Find all two-hop routes ending at JFK, not starting at JFK
console.log('=== One-stop routes to JFK (origin != JFK) ===');
let found = false;
for (const origin of Object.keys(adj)) {
  if (origin === 'JFK') continue;
  for (const leg1 of adj[origin]) {
    const mid = leg1.destination;
    if (mid === 'JFK') continue; // that's direct, not one-stop
    if (adj[mid]) {
      for (const leg2 of adj[mid]) {
        if (leg2.destination === 'JFK') {
          found = true;
          console.log('Route: ' + origin + ' -> ' + mid + ' -> JFK');
          console.log('  Leg 1: ' + leg1.flight_id + ' (' + origin + '->' + mid + ') departs ' + leg1.departure_time + ', arrives ' + leg1.arrival_time);
          console.log('    Prices: ' + leg1.cabin_prices_json);
          console.log('    Dates: ' + leg1.dates_json);
          console.log('    Skill: ' + leg1.source_skill);
          console.log('  Leg 2: ' + leg2.flight_id + ' (' + mid + '->JFK) departs ' + leg2.departure_time + ', arrives ' + leg2.arrival_time);
          console.log('    Prices: ' + leg2.cabin_prices_json);
          console.log('    Dates: ' + leg2.dates_json);
          console.log('    Skill: ' + leg2.source_skill);
          console.log('');
        }
      }
    }
  }
}
if (!found) console.log('No one-stop routes to JFK found.');
"
